pub(super) fn restore_oram_storage_from_old(
    state: &mut OramState,
    spec: &StateObject,
    old: &OramState,
) -> Result<()> {
    if state.parameters != old.parameters {
        bail!(
            "cannot restore ORAM state for {} across differing public parameters",
            spec.name
        );
    }
    if state.storage.directory_pages.len() != old.storage.directory_pages.len() {
        bail!(
            "directory page buffer length {} mismatched public page count {} for {}",
            state.storage.directory_pages.len(),
            old.storage.directory_pages.len(),
            spec.name
        );
    }
    if state.storage.buckets.len() != old.storage.buckets.len() {
        bail!(
            "bucket buffer length {} mismatched public bucket count {} for {}",
            state.storage.buckets.len(),
            old.storage.buckets.len(),
            spec.name
        );
    }
    if state.storage.access_counter_slot.len() != old.storage.access_counter_slot.len() {
        bail!(
            "counter buffer length {} mismatched public counter size {} for {}",
            state.storage.access_counter_slot.len(),
            old.storage.access_counter_slot.len(),
            spec.name
        );
    }
    state
        .storage
        .directory_pages
        .clone_from(&old.storage.directory_pages);
    state.storage.buckets.clone_from(&old.storage.buckets);
    state
        .storage
        .access_counter_slot
        .clone_from(&old.storage.access_counter_slot);
    state.access_counter = old.access_counter;
    Ok(())
}

