fn sample_leaf(rng: &mut ChaCha20Rng, leaf_count: usize) -> usize {
    (rng.next_u64() as usize) % leaf_count.max(1)
}

impl Drop for PathOramLeafCoinSource {
    fn drop(&mut self) {
        if let Self::Injected { coins, next_index } = self {
            for leaf in coins.iter_mut() {
                *leaf = 0;
            }
            *next_index = 0;
        }
    }
}

impl PathOramLeafCoinSource {
    pub(crate) fn random() -> Self {
        Self::Random
    }

    pub(crate) fn require_injected() -> Self {
        Self::Injected {
            coins: Box::<[usize]>::default(),
            next_index: 0,
        }
    }

    pub(crate) fn install(&mut self, coins: Box<[usize]>) {
        *self = Self::Injected {
            coins,
            next_index: 0,
        };
    }

    pub(crate) fn take_leaf(
        &mut self,
        object_name: &str,
        leaf_count: usize,
        rng: &mut ChaCha20Rng,
    ) -> Result<usize> {
        match self {
            Self::Random => Ok(sample_leaf(rng, leaf_count)),
            Self::Injected { coins, next_index } => {
                let leaf = coins.get(*next_index).copied().ok_or_else(|| {
                    anyhow!(
                        "path ORAM object {} requires injected fresh-leaf coins, but the tape is exhausted",
                        object_name
                    )
                })?;
                *next_index += 1;
                if leaf >= leaf_count.max(1) {
                    bail!(
                        "path ORAM object {} received injected leaf {} outside leaf count {}",
                        object_name,
                        leaf,
                        leaf_count.max(1)
                    );
                }
                Ok(leaf)
            }
        }
    }

    pub(crate) fn ensure_exhausted(&self, object_name: &str) -> Result<()> {
        match self {
            Self::Random => Ok(()),
            Self::Injected { coins, next_index } if *next_index == coins.len() => Ok(()),
            Self::Injected { coins, next_index } => bail!(
                "path ORAM object {} left {} injected fresh-leaf coins unused",
                object_name,
                coins.len() - *next_index
            ),
        }
    }
}

pub(super) fn surrogate_access_transcript(
    state: &OramState,
    spec: &StateObject,
) -> Result<OramTranscript> {
    if state.storage.directory_pages.len() != state.parameters.metadata_pages {
        bail!(
            "surrogate ORAM transcript directory page count {} mismatched public bound {} for {}",
            state.storage.directory_pages.len(),
            state.parameters.metadata_pages,
            spec.name
        );
    }
    if state.storage.buckets.len() != state.parameters.bucket_count {
        bail!(
            "surrogate ORAM transcript bucket count {} mismatched public bound {} for {}",
            state.storage.buckets.len(),
            state.parameters.bucket_count,
            spec.name
        );
    }
    let public_access_count =
        1 + state.storage.directory_pages.len() + state.parameters.buckets_per_access;
    let mut logical_accesses = FixedBoxBuilder::new(public_access_count);
    let mut physical_reads = FixedBoxBuilder::new(public_access_count);

    logical_accesses.push(LogicalEvent {
        kind: "uooram_counter".into(),
        object: spec.name.clone(),
        detail: "counter".into(),
    })?;
    physical_reads.push(PhysicalReadEvent {
        object: spec.name.clone(),
        location: format!("{}@counter", spec.name),
        len: state.storage.access_counter_slot.len(),
    })?;

    for page in 0..state.storage.directory_pages.len() {
        let directory_page = state.storage.directory_pages.get(page).ok_or_else(|| {
            anyhow!(
                "surrogate ORAM transcript directory page index {} missing despite public count guard for {}",
                page,
                spec.name
            )
        })?;
        logical_accesses.push(LogicalEvent {
            kind: "uooram_meta_scan".into(),
            object: spec.name.clone(),
            detail: format!("page:{page}"),
        })?;
        physical_reads.push(PhysicalReadEvent {
            object: spec.name.clone(),
            location: format!("{}@meta{page}", spec.name),
            len: directory_page.len(),
        })?;
    }

    let bucket_count = state.storage.buckets.len();
    if bucket_count != 0 {
        for offset in 0..state.parameters.buckets_per_access {
            let index = ((state.access_counter as usize) + offset) % bucket_count;
            let bucket = state.storage.buckets.get(index).ok_or_else(|| {
                anyhow!(
                    "surrogate ORAM transcript bucket index {} missing despite public count guard for {}",
                    index,
                    spec.name
                )
            })?;
            logical_accesses.push(LogicalEvent {
                kind: "uooram_bucket_scan".into(),
                object: spec.name.clone(),
                detail: format!("bucket:{index}"),
            })?;
            physical_reads.push(PhysicalReadEvent {
                object: spec.name.clone(),
                location: format!("{}@bucket{index}", spec.name),
                len: bucket.len(),
            })?;
        }
    }

    Ok(OramTranscript {
        logical_accesses: logical_accesses.finish()?,
        physical_reads: physical_reads.finish()?,
        physical_writes: empty_oram_write_batch(),
        path_leaf: None,
        path_transition: None,
    })
}

pub(super) fn path_access_transcript(
    state: &OramState,
    spec: &StateObject,
    leaf: usize,
) -> Result<OramTranscript> {
    if state.storage.directory_pages.len() != state.parameters.metadata_pages {
        bail!(
            "path ORAM transcript directory page count {} mismatched public bound {} for {}",
            state.storage.directory_pages.len(),
            state.parameters.metadata_pages,
            spec.name
        );
    }
    if state.storage.buckets.len() != state.parameters.bucket_count {
        bail!(
            "path ORAM transcript bucket count {} mismatched public bound {} for {}",
            state.storage.buckets.len(),
            state.parameters.bucket_count,
            spec.name
        );
    }
    let public_access_count =
        1 + state.storage.directory_pages.len() + state.parameters.buckets_per_access;
    let mut logical_accesses = FixedBoxBuilder::new(public_access_count);
    let mut physical_reads = FixedBoxBuilder::new(public_access_count);

    logical_accesses.push(LogicalEvent {
        kind: "uooram_counter".into(),
        object: spec.name.clone(),
        detail: "counter".into(),
    })?;
    physical_reads.push(PhysicalReadEvent {
        object: spec.name.clone(),
        location: format!("{}@counter", spec.name),
        len: state.storage.access_counter_slot.len(),
    })?;

    for page in 0..state.storage.directory_pages.len() {
        let directory_page = state.storage.directory_pages.get(page).ok_or_else(|| {
            anyhow!(
                "path ORAM transcript directory page index {} missing despite public count guard for {}",
                page,
                spec.name
            )
        })?;
        logical_accesses.push(LogicalEvent {
            kind: "uooram_metadata_load".into(),
            object: spec.name.clone(),
            detail: format!("page:{page}"),
        })?;
        physical_reads.push(PhysicalReadEvent {
            object: spec.name.clone(),
            location: format!("{}@meta{page}", spec.name),
            len: directory_page.len(),
        })?;
    }

    let mut transcript_result = Ok(());
    for_each_bucket_on_leaf_path_root_to_leaf(state.parameters.leaf_count(), leaf, |index| {
        if transcript_result.is_err() {
            return;
        }
        transcript_result = (|| -> Result<()> {
            let bucket = state.storage.buckets.get(index).ok_or_else(|| {
                anyhow!(
                    "path ORAM transcript bucket index {} missing despite public count guard for {}",
                    index,
                    spec.name
                )
            })?;
            logical_accesses.push(LogicalEvent {
                kind: "uooram_path_read".into(),
                object: spec.name.clone(),
                detail: format!("bucket:{index}"),
            })?;
            physical_reads.push(PhysicalReadEvent {
                object: spec.name.clone(),
                location: format!("{}@bucket{index}", spec.name),
                len: bucket.len(),
            })?;
            Ok(())
        })();
    });
    transcript_result?;

    Ok(OramTranscript {
        logical_accesses: logical_accesses.finish()?,
        physical_reads: physical_reads.finish()?,
        physical_writes: empty_oram_write_batch(),
        path_leaf: Some(leaf),
        path_transition: None,
    })
}

pub(super) fn oram_meta_aad(spec: &StateObject, page: usize) -> String {
    format!("oram:{}:meta:{page}", spec.name)
}

pub(super) fn oram_bucket_aad(spec: &StateObject, index: usize) -> String {
    format!("oram:{}:bucket:{index}", spec.name)
}

pub(super) fn oram_counter_aad(spec: &StateObject) -> String {
    format!("oram:{}:counter", spec.name)
}

pub(super) fn bootstrap_oram_counter_slot(
    spec: &StateObject,
    cipher: &StoreCipher,
    rng: &mut ChaCha20Rng,
) -> Result<Box<[u8]>> {
    let mut payload = 0u64.to_be_bytes();
    seal_boxed_oram_payload(&oram_counter_aad(spec), &mut payload, cipher, rng, None)
}

pub(super) fn read_oram_counter_from_storage(
    spec: &StateObject,
    cipher: &StoreCipher,
    allocator: &mut AllocatorSession,
    access_counter_slot: &[u8],
) -> Result<u64> {
    with_opened_oram_payload(
        format!("{}@counter", spec.name),
        oram_counter_aad(spec),
        8,
        access_counter_slot,
        cipher,
        allocator,
        |counter_bytes| read_u64_be_at(counter_bytes, 0, "reading ORAM access counter"),
    )
}

pub(super) fn bootstrap_surrogate_directory_pages(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    entries: &[MapEntry],
    empty_entry: &MapEntry,
    rng: &mut ChaCha20Rng,
) -> Result<Box<[Box<[u8]>]>> {
    let mut pages = FixedBoxBuilder::new(parameters.metadata_pages);
    for page in 0..parameters.metadata_pages {
        let mut payload = zeroed_boxed_bytes(parameters.directory_page_bytes)?;
        encode_oram_directory_page_into(
            directory_page_entries(entries, page),
            empty_entry,
            payload.as_mut(),
        )?;
        let aad = oram_meta_aad(spec, page);
        pages.push(seal_boxed_oram_payload(
            &aad,
            payload.as_mut(),
            cipher,
            rng,
            None,
        )?)?;
    }
    pages.finish()
}

pub(super) fn bootstrap_filler_buckets(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    rng: &mut ChaCha20Rng,
) -> Result<Box<[Box<[u8]>]>> {
    let mut buckets = FixedBoxBuilder::new(parameters.bucket_count);
    for index in 0..parameters.bucket_count {
        let aad = oram_bucket_aad(spec, index);
        buckets.push(filler_boxed_oram_payload(
            &aad,
            parameters.bucket_size,
            cipher,
            rng,
        )?)?;
    }
    buckets.finish()
}

pub(super) fn bootstrap_empty_path_buckets(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    rng: &mut ChaCha20Rng,
) -> Result<Box<[Box<[u8]>]>> {
    let mut buckets = FixedBoxBuilder::new(parameters.bucket_count);
    for index in 0..parameters.bucket_count {
        let aad = oram_bucket_aad(spec, index);
        let empty_bucket = oram_bucket_with_live_blocks(spec, 0, index, 0, &[])?;
        let mut payload = oram_bucket_bytes(&empty_bucket, spec)?;
        buckets.push(seal_boxed_oram_payload(
            &aad,
            payload.as_mut(),
            cipher,
            rng,
            None,
        )?)?;
    }
    buckets.finish()
}

pub(super) fn rewrite_oram_counter_in_place(
    spec: &StateObject,
    next_counter: u64,
    cipher: &StoreCipher,
    allocator: &mut AllocatorSession,
    rng: &mut ChaCha20Rng,
    access_counter_slot: &mut [u8],
    writes: &mut OramWriteLog,
) -> Result<()> {
    let mut payload = next_counter.to_be_bytes();
    reseal_oram_payload_and_record_write(
        writes,
        format!("{}@counter", spec.name),
        oram_counter_aad(spec),
        &mut payload,
        access_counter_slot,
        cipher,
        rng,
        allocator,
    )
}

pub(super) fn rewrite_surrogate_directory_pages_in_place(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    entries: &[MapEntry],
    empty_entry: &MapEntry,
    allocator: &mut AllocatorSession,
    rng: &mut ChaCha20Rng,
    directory_pages: &mut [Box<[u8]>],
    writes: &mut OramWriteLog,
) -> Result<()> {
    if directory_pages.len() != parameters.metadata_pages {
        bail!(
            "surrogate ORAM directory page count {} did not match public metadata count {} for {}",
            directory_pages.len(),
            parameters.metadata_pages,
            spec.name
        );
    }
    for page in 0..directory_pages.len() {
        let directory_page = directory_pages.get_mut(page).ok_or_else(|| {
            anyhow!(
                "surrogate ORAM directory page index {} missing despite public count guard for {}",
                page,
                spec.name
            )
        })?;
        let mut payload = zeroed_boxed_bytes(parameters.directory_page_bytes)?;
        encode_oram_directory_page_into(
            directory_page_entries(entries, page),
            empty_entry,
            payload.as_mut(),
        )?;
        reseal_oram_payload_and_record_write(
            writes,
            format!("{}@meta{page}", spec.name),
            oram_meta_aad(spec, page),
            payload.as_mut(),
            directory_page,
            cipher,
            rng,
            allocator,
        )?;
    }
    Ok(())
}

pub(super) fn rewrite_surrogate_bucket_window_in_place(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    entries: &[MapEntry],
    access_counter: u64,
    allocator: &mut AllocatorSession,
    rng: &mut ChaCha20Rng,
    buckets: &mut [Box<[u8]>],
    writes: &mut OramWriteLog,
) -> Result<()> {
    if buckets.len() != parameters.bucket_count {
        bail!(
            "surrogate ORAM bucket count {} did not match public bucket count {} for {}",
            buckets.len(),
            parameters.bucket_count,
            spec.name
        );
    }
    for_each_surrogate_bucket_window(
        parameters.buckets_per_access,
        access_counter as usize,
        buckets.len(),
        |index| {
            let bucket = oram_bucket_from_entries(spec, entries, access_counter, index)?;
            let mut payload = oram_bucket_bytes(&bucket, spec)?;
            let sealed_bucket = buckets.get_mut(index).ok_or_else(|| {
                anyhow!(
                    "surrogate ORAM bucket index {} missing despite public count guard for {}",
                    index,
                    spec.name
                )
            })?;
            reseal_oram_payload_and_record_write(
                writes,
                format!("{}@bucket{index}", spec.name),
                oram_bucket_aad(spec, index),
                payload.as_mut(),
                sealed_bucket,
                cipher,
                rng,
                allocator,
            )?;
            Ok::<(), anyhow::Error>(())
        },
    )
}

pub(super) fn directory_page_entries<T>(entries: &[T], page: usize) -> &[T] {
    let start = page.saturating_mul(ORAM_DIRECTORY_PAGE_ENTRIES);
    if start >= entries.len() {
        &[]
    } else {
        let take = entries
            .len()
            .saturating_sub(start)
            .min(ORAM_DIRECTORY_PAGE_ENTRIES);
        let end = start.saturating_add(take);
        match entries.get(start..end) {
            Some(page_entries) => page_entries,
            None => &[],
        }
    }
}

fn levels_for_leaf_count(leaf_count: usize) -> usize {
    let leaf_count = leaf_count.max(1);
    let mut levels = 0usize;
    let mut width = leaf_count;
    while width > 0 {
        levels += 1;
        width /= 2;
    }
    levels
}

fn path_bucket_at_depth(leaf_count: usize, leaf: usize, depth: usize) -> usize {
    let leaf_count = leaf_count.max(1);
    let levels = levels_for_leaf_count(leaf_count);
    let mut node = leaf_count - 1 + (leaf % leaf_count);
    let ascents = levels.saturating_sub(1).saturating_sub(depth);
    for _ in 0..ascents {
        node = node.saturating_sub(1) / 2;
    }
    node
}

#[cfg(test)]
pub(super) fn path_bucket_indices(leaf_count: usize, leaf: usize) -> Vec<usize> {
    let levels = levels_for_leaf_count(leaf_count);
    let mut path = Vec::new();
    for depth in 0..levels {
        path.push(path_bucket_at_depth(leaf_count, leaf, depth));
    }
    path
}

pub(super) fn for_each_surrogate_bucket_window<E, F>(
    buckets_per_access: usize,
    access_counter: usize,
    bucket_count: usize,
    mut f: F,
) -> Result<(), E>
where
    F: FnMut(usize) -> Result<(), E>,
{
    for offset in 0..buckets_per_access {
        f((access_counter + offset) % bucket_count)?;
    }
    Ok(())
}

pub(super) fn for_each_bucket_on_leaf_path_root_to_leaf<F>(leaf_count: usize, leaf: usize, mut f: F)
where
    F: FnMut(usize),
{
    let levels = levels_for_leaf_count(leaf_count);
    for depth in 0..levels {
        f(path_bucket_at_depth(leaf_count, leaf, depth));
    }
}

pub(super) fn for_each_bucket_on_leaf_path_leaf_to_root<F>(leaf_count: usize, leaf: usize, mut f: F)
where
    F: FnMut(usize),
{
    let levels = levels_for_leaf_count(leaf_count);
    for offset in 0..levels {
        let depth = levels - 1 - offset;
        f(path_bucket_at_depth(leaf_count, leaf, depth));
    }
}

pub(super) fn bucket_on_leaf_path(leaf_count: usize, bucket_index: usize, leaf: usize) -> bool {
    let leaf_count = leaf_count.max(1);
    let levels = levels_for_leaf_count(leaf_count);
    let mut node = leaf_count - 1 + (leaf % leaf_count);
    let mut found = false;
    for _ in 0..levels {
        found |= node == bucket_index;
        let parent = node.saturating_sub(1) / 2;
        node = masked_select_usize(node != 0, parent, 0);
    }
    found
}

pub(super) fn validate_live_path_block(
    spec: &StateObject,
    parameters: &OramParameters,
    position_map: &[MaskedUsizeOption],
    live_slots: &mut [MaskedUsizeOption],
    block: &OramBlock,
) -> Result<()> {
    if position_map.len() != parameters.capacity {
        bail!(
            "position-map buffer length {} mismatched public capacity {} for {}",
            position_map.len(),
            parameters.capacity,
            spec.name
        );
    }
    if live_slots.len() != parameters.capacity {
        bail!(
            "live-slot buffer length {} mismatched public capacity {} for {}",
            live_slots.len(),
            parameters.capacity,
            spec.name
        );
    }
    let occupied = block.occupied;
    let slot_in_range = block.slot_index < position_map.len();
    if occupied & !slot_in_range {
        bail!(
            "decoded ORAM live block for {} references out-of-range slot {}",
            spec.name,
            block.slot_index
        );
    }
    if occupied & (block.leaf >= parameters.leaf_count()) {
        bail!(
            "decoded ORAM live block for {} carries out-of-range leaf {}",
            spec.name,
            block.leaf
        );
    }
    let slot_index = masked_select_usize(slot_in_range, block.slot_index, 0);
    let expected_leaf = position_map.get(slot_index).ok_or_else(|| {
        anyhow!(
            "position-map slot index {} missing despite public capacity guard for {}",
            slot_index,
            spec.name
        )
    })?;
    if occupied & !expected_leaf.is_some() {
        bail!(
            "decoded ORAM live block for {} has slot {} but position map is empty there",
            spec.name,
            block.slot_index
        );
    }
    let expected_leaf_value = expected_leaf.unwrap_or(0);
    if occupied & (expected_leaf_value != block.leaf) {
        bail!(
            "decoded ORAM live block for {} disagrees with position map at slot {}: {} != {}",
            spec.name,
            block.slot_index,
            block.leaf,
            expected_leaf_value
        );
    }
    let live_slot = live_slots.get(slot_index).ok_or_else(|| {
        anyhow!(
            "live-slot index {} missing despite public capacity guard for {}",
            slot_index,
            spec.name
        )
    })?;
    if occupied & live_slot.is_some() {
        bail!(
            "decoded ORAM state for {} contains duplicate live blocks for slot {}",
            spec.name,
            block.slot_index
        );
    }
    let selected_live_slot =
        masked_select_option_usize(occupied, &MaskedUsizeOption::some(block.leaf), live_slot);
    let live_slot = live_slots.get_mut(slot_index).ok_or_else(|| {
        anyhow!(
            "live-slot index {} missing despite public capacity guard for {}",
            slot_index,
            spec.name
        )
    })?;
    assign_masked_usize_option(live_slot, &selected_live_slot);
    Ok(())
}

pub(super) fn masked_select_usize(cond: bool, when_true: usize, when_false: usize) -> usize {
    let mask = 0usize.wrapping_sub(cond as usize);
    (when_true & mask) | (when_false & !mask)
}

pub(super) fn masked_select_u64(cond: bool, when_true: u64, when_false: u64) -> u64 {
    let mask = 0u64.wrapping_sub(cond as u64);
    (when_true & mask) | (when_false & !mask)
}

pub(super) fn masked_select_bool(cond: bool, when_true: bool, when_false: bool) -> bool {
    masked_select_usize(cond, usize::from(when_true), usize::from(when_false)) != 0
}

#[derive(Debug, Default, PartialEq, Eq)]
pub(crate) struct MaskedUsizeOption {
    present: bool,
    value: usize,
}

impl MaskedUsizeOption {
    pub(crate) fn none() -> Self {
        Self {
            present: false,
            value: 0,
        }
    }

    pub(crate) fn some(value: usize) -> Self {
        Self {
            present: true,
            value,
        }
    }

    pub(crate) fn new(present: bool, value: usize) -> Self {
        Self { present, value }
    }

    #[cfg(test)]
    pub(crate) fn from_option(value: Option<usize>) -> Self {
        Self {
            present: value.is_some(),
            value: value.unwrap_or(0),
        }
    }

    #[cfg(test)]
    pub(crate) fn to_option(&self) -> Option<usize> {
        if self.present {
            Some(self.value)
        } else {
            None
        }
    }

    pub(crate) fn to_witness(&self) -> RuntimeMaskedUsizeOptionWitness {
        RuntimeMaskedUsizeOptionWitness {
            present: self.present,
            value: self.value,
        }
    }

    pub(crate) fn is_some(&self) -> bool {
        self.present
    }

    pub(crate) fn unwrap_or(&self, default: usize) -> usize {
        masked_select_usize(self.present, self.value, default)
    }
}

fn clone_masked_usize_option(value: &MaskedUsizeOption) -> MaskedUsizeOption {
    MaskedUsizeOption {
        present: value.present,
        value: value.value,
    }
}

fn assign_masked_usize_option(target: &mut MaskedUsizeOption, source: &MaskedUsizeOption) {
    target.present = source.present;
    target.value = source.value;
}

pub(super) fn repeat_boxed_masked_usize_options(
    len: usize,
    value: &MaskedUsizeOption,
) -> Result<Box<[MaskedUsizeOption]>> {
    let mut values = FixedBoxBuilder::new(len);
    for _ in 0..len {
        values.push(clone_masked_usize_option(value))?;
    }
    values.finish()
}

pub(super) fn masked_select_option_usize(
    cond: bool,
    when_true: &MaskedUsizeOption,
    when_false: &MaskedUsizeOption,
) -> MaskedUsizeOption {
    MaskedUsizeOption {
        present: masked_select_bool(cond, when_true.present, when_false.present),
        value: masked_select_usize(cond, when_true.value, when_false.value),
    }
}

pub(super) fn masked_select_transition_kind(
    cond: bool,
    when_true: RuntimePathOramTransitionKind,
    when_false: RuntimePathOramTransitionKind,
) -> RuntimePathOramTransitionKind {
    let true_tag = match when_true {
        RuntimePathOramTransitionKind::ReadMiss => 0u8,
        RuntimePathOramTransitionKind::ReadHit => 1u8,
        RuntimePathOramTransitionKind::WriteNoop => 2u8,
        RuntimePathOramTransitionKind::WriteInsert => 3u8,
        RuntimePathOramTransitionKind::WriteUpdate => 4u8,
        RuntimePathOramTransitionKind::WriteDelete => 5u8,
    };
    let false_tag = match when_false {
        RuntimePathOramTransitionKind::ReadMiss => 0u8,
        RuntimePathOramTransitionKind::ReadHit => 1u8,
        RuntimePathOramTransitionKind::WriteNoop => 2u8,
        RuntimePathOramTransitionKind::WriteInsert => 3u8,
        RuntimePathOramTransitionKind::WriteUpdate => 4u8,
        RuntimePathOramTransitionKind::WriteDelete => 5u8,
    };
    match masked_select_usize(cond, true_tag as usize, false_tag as usize) as u8 {
        0 => RuntimePathOramTransitionKind::ReadMiss,
        1 => RuntimePathOramTransitionKind::ReadHit,
        2 => RuntimePathOramTransitionKind::WriteNoop,
        3 => RuntimePathOramTransitionKind::WriteInsert,
        4 => RuntimePathOramTransitionKind::WriteUpdate,
        _ => RuntimePathOramTransitionKind::WriteDelete,
    }
}

pub(super) fn select_position_map_leaf(
    position_map: &[MaskedUsizeOption],
    slot: &MaskedUsizeOption,
) -> MaskedUsizeOption {
    let slot_index = slot.unwrap_or(0);
    let slot_present = slot.is_some();
    let mut selected = MaskedUsizeOption::none();
    for (index, leaf) in position_map.iter().enumerate() {
        let take_here = slot_present & (index == slot_index);
        selected = masked_select_option_usize(take_here, leaf, &selected);
    }
    selected
}

pub(super) fn select_entry_value_for_slot(
    entries: &[MapEntry],
    slot: &MaskedUsizeOption,
    value_type: &Type,
) -> Result<Value> {
    let slot_index = slot.unwrap_or(0);
    let slot_present = slot.is_some();
    let mut selected = Value::zero_for_type(value_type);
    for (index, entry) in entries.iter().enumerate() {
        let take_here = slot_present & (index == slot_index);
        selected = Value::confidential_select(take_here, entry.value().clone(), selected)?;
    }
    Ok(selected)
}

pub(super) fn select_stash_index(
    stash: &FixedStash,
    predicate: impl FnMut(&OramBlock) -> bool,
) -> MaskedUsizeOption {
    select_stash_index_with_limit(stash, stash.blocks.len(), predicate)
}

pub(super) fn select_stash_index_with_limit(
    stash: &FixedStash,
    limit: usize,
    mut predicate: impl FnMut(&OramBlock) -> bool,
) -> MaskedUsizeOption {
    let public_limit = limit.min(stash.blocks.len());
    let mut selected = 0usize;
    let mut present = false;
    for (index, block) in stash.blocks.iter().enumerate() {
        let matches = (index < public_limit) & predicate(block);
        let choose_here = !present & matches;
        selected = masked_select_usize(choose_here, index, selected);
        present |= matches;
    }
    MaskedUsizeOption::new(present, selected)
}

pub(super) fn take_selected_stash_block(
    stash: &mut FixedStash,
    selected_index: usize,
    present: bool,
) -> Result<OramBlock> {
    let mut removed = clone_oram_block(&stash.empty_block);
    for (index, block) in stash.blocks.iter_mut().enumerate() {
        let take_here = present & (index == selected_index);
        removed = select_oram_block(take_here, block, &removed)?;
        *block = select_oram_block(take_here, &stash.empty_block, block)?;
    }
    stash.len = stash.len.saturating_sub(usize::from(present));
    Ok(removed)
}

pub(super) fn slot_for_key(entries: &[MapEntry], key: &Value) -> MaskedUsizeOption {
    let mut selected = 0usize;
    let mut present = false;
    for (index, entry) in entries.iter().enumerate() {
        let is_match = entry.matches_key(key);
        let match_here = !present & is_match;
        selected = masked_select_usize(match_here, index, selected);
        present |= is_match;
    }
    MaskedUsizeOption::new(present, selected)
}

pub(super) fn allocate_slot(entries: &[MapEntry]) -> MaskedUsizeOption {
    let mut selected = 0usize;
    let mut present = false;
    for (index, entry) in entries.iter().enumerate() {
        let is_vacant = !entry.is_occupied();
        let match_here = !present & is_vacant;
        selected = masked_select_usize(match_here, index, selected);
        present |= is_vacant;
    }
    MaskedUsizeOption::new(present, selected)
}

pub(super) fn access_leaf_for_key(
    entries: &[MapEntry],
    position_map: &[MaskedUsizeOption],
    key: &Value,
    fresh_leaf: usize,
) -> usize {
    let slot = slot_for_key(entries, key);
    let prior_leaf = select_position_map_leaf(position_map, &slot);
    masked_select_usize(prior_leaf.is_some(), prior_leaf.unwrap_or(0), fresh_leaf)
}

pub(super) fn apply_path_get_update(
    position_map: &mut [MaskedUsizeOption],
    stash: &mut FixedStash,
    slot: &MaskedUsizeOption,
    next_leaf: &MaskedUsizeOption,
) {
    let slot_present = slot.is_some();
    let slot_index = slot.unwrap_or(0);
    let next_leaf_present = next_leaf.is_some();
    let next_leaf_value = next_leaf.unwrap_or(0);
    for (index, leaf) in position_map.iter_mut().enumerate() {
        let update_here = slot_present & next_leaf_present & (index == slot_index);
        let selected_leaf = masked_select_option_usize(update_here, next_leaf, leaf);
        assign_masked_usize_option(leaf, &selected_leaf);
    }
    for block in stash.blocks.iter_mut() {
        let update_here =
            slot_present & next_leaf_present & block.occupied & (block.slot_index == slot_index);
        block.leaf = masked_select_usize(update_here, next_leaf_value, block.leaf);
    }
}

pub(super) fn apply_path_put_update(
    spec: &StateObject,
    entries: &mut [MapEntry],
    position_map: &mut [MaskedUsizeOption],
    stash: &mut FixedStash,
    key: &Value,
    value: &Value,
    apply: bool,
    slot: &MaskedUsizeOption,
    insert_slot: &MaskedUsizeOption,
    next_leaf: &MaskedUsizeOption,
) -> Result<bool> {
    let slot_present = slot.is_some();
    let slot_index = slot.unwrap_or(0);
    let insert_slot_present = insert_slot.is_some();
    let insert_slot_index = insert_slot.unwrap_or(0);
    let value_is_zero = value.confidential_is_zero_like();
    let update_existing = apply & slot_present & !value_is_zero;
    let delete_existing = apply & slot_present & value_is_zero;
    let insert_new = apply & !slot_present & !value_is_zero & insert_slot_present;
    let next_leaf_value = next_leaf.unwrap_or(0);
    let key_type = spec
        .key_type
        .as_ref()
        .ok_or_else(|| anyhow!("map {} missing key type", spec.name))?;
    let zero_key = Value::zero_for_type(key_type);
    let zero_value = Value::zero_for_type(&spec.value_type);

    for (index, entry) in entries.iter_mut().enumerate() {
        let update_here = update_existing & (index == slot_index);
        let delete_here = delete_existing & (index == slot_index);
        let insert_here = insert_new & (index == insert_slot_index);
        let prior_key = entry.key().clone();
        let prior_value = entry.value().clone();
        let selected_key = Value::confidential_select(insert_here, key.clone(), prior_key)?;
        let next_key = Value::confidential_select(delete_here, zero_key.clone(), selected_key)?;
        let selected_value =
            Value::confidential_select(update_here | insert_here, value.clone(), prior_value)?;
        let next_value =
            Value::confidential_select(delete_here, zero_value.clone(), selected_value)?;
        let next_occupied = (entry.is_occupied() & !delete_here) | update_here | insert_here;
        entry.overwrite(next_occupied, next_key, next_value);
    }

    for (index, leaf) in position_map.iter_mut().enumerate() {
        let update_here = update_existing & (index == slot_index);
        let delete_here = delete_existing & (index == slot_index);
        let insert_here = insert_new & (index == insert_slot_index);
        let selected_leaf = masked_select_option_usize(update_here, next_leaf, leaf);
        let empty_leaf = MaskedUsizeOption::none();
        let cleared_leaf = masked_select_option_usize(delete_here, &empty_leaf, &selected_leaf);
        let updated_leaf = masked_select_option_usize(insert_here, next_leaf, &cleared_leaf);
        assign_masked_usize_option(leaf, &updated_leaf);
    }

    let mut matched_slot = false;
    let mut inserted_slot = false;
    for block in stash.blocks.iter_mut() {
        let was_occupied = block.occupied;
        let slot_match = was_occupied & slot_present & (block.slot_index == slot_index);
        let update_here = update_existing & slot_match;
        let delete_here = delete_existing & slot_match;
        let insert_here = insert_new & !inserted_slot & !was_occupied;
        let prior_key = block.key.clone();
        let prior_value = block.value.clone();
        let next_slot_index = masked_select_usize(
            insert_here,
            insert_slot_index,
            masked_select_usize(delete_here, 0, block.slot_index),
        );
        let selected_leaf =
            masked_select_usize(update_here | insert_here, next_leaf_value, block.leaf);
        let next_leaf_label = masked_select_usize(delete_here, 0, selected_leaf);
        let selected_key = Value::confidential_select(insert_here, key.clone(), prior_key)?;
        let next_key = Value::confidential_select(delete_here, zero_key.clone(), selected_key)?;
        let selected_value =
            Value::confidential_select(update_here | insert_here, value.clone(), prior_value)?;
        let next_value =
            Value::confidential_select(delete_here, zero_value.clone(), selected_value)?;
        let next_occupied = (was_occupied & !delete_here) | insert_here;
        block.overwrite(
            next_occupied,
            next_slot_index,
            next_leaf_label,
            next_key,
            next_value,
        );
        matched_slot |= slot_match;
        inserted_slot |= insert_here;
    }

    stash.len = stash
        .blocks
        .iter()
        .fold(0usize, |acc, block| acc + usize::from(block.occupied));
    let update_failed = ((update_existing | delete_existing) & !matched_slot)
        | (insert_new & !inserted_slot)
        | (insert_new & (insert_slot_index >= entries.len()));
    let _ = spec;
    Ok(update_failed)
}

pub(super) fn apply_surrogate_put_update(
    spec: &StateObject,
    entries: &mut [MapEntry],
    key: &Value,
    value: &Value,
    apply: bool,
    slot: &MaskedUsizeOption,
    insert_slot: &MaskedUsizeOption,
) -> Result<bool> {
    let slot_present = slot.is_some();
    let slot_index = slot.unwrap_or(0);
    let value_is_zero = value.confidential_is_zero_like();
    let request_insert = apply & !slot_present & !value_is_zero;
    let insert_slot_present = insert_slot.is_some();
    let insert_slot_index = insert_slot.unwrap_or(0);
    let key_type = spec
        .key_type
        .as_ref()
        .ok_or_else(|| anyhow!("map {} missing key type", spec.name))?;
    let zero_key = Value::zero_for_type(key_type);
    let zero_value = Value::zero_for_type(&spec.value_type);

    for (index, entry) in entries.iter_mut().enumerate() {
        let update_here = apply & slot_present & !value_is_zero & (index == slot_index);
        let delete_here = apply & slot_present & value_is_zero & (index == slot_index);
        let insert_here = apply
            & !slot_present
            & !value_is_zero
            & insert_slot_present
            & (index == insert_slot_index);
        let prior_key = entry.key().clone();
        let prior_value = entry.value().clone();
        let selected_key = Value::confidential_select(insert_here, key.clone(), prior_key)?;
        let next_key = Value::confidential_select(delete_here, zero_key.clone(), selected_key)?;
        let selected_value =
            Value::confidential_select(update_here | insert_here, value.clone(), prior_value)?;
        let next_value =
            Value::confidential_select(delete_here, zero_value.clone(), selected_value)?;
        let next_occupied = (entry.is_occupied() & !delete_here) | update_here | insert_here;
        entry.overwrite(next_occupied, next_key, next_value);
    }

    let capacity_overflowed = request_insert & !insert_slot_present;
    let _ = spec;
    Ok(capacity_overflowed)
}

pub(super) fn run_surrogate_get(
    state: &OramState,
    spec: &StateObject,
    key: &Value,
) -> Result<(Value, OramTranscript, bool)> {
    let slot = slot_for_key(&state.entries, key);
    let value = select_entry_value_for_slot(&state.entries, &slot, &spec.value_type)?;
    Ok((value, surrogate_access_transcript(state, spec)?, false))
}

pub(super) fn run_surrogate_put(
    state: &mut OramState,
    spec: &StateObject,
    key: Value,
    value: Value,
    apply: bool,
) -> Result<(OramTranscript, bool)> {
    let transcript = surrogate_access_transcript(state, spec)?;
    let slot = slot_for_key(&state.entries, &key);
    let slot_present = slot.is_some();
    let value_is_zero = value.confidential_is_zero_like();
    let request_insert = apply & !slot_present & !value_is_zero;
    let vacant_slot = allocate_slot(&state.entries);
    let no_insert_slot = MaskedUsizeOption::none();
    let insert_slot = masked_select_option_usize(request_insert, &vacant_slot, &no_insert_slot);
    let capacity_overflowed = apply_surrogate_put_update(
        spec,
        &mut state.entries,
        &key,
        &value,
        apply,
        &slot,
        &insert_slot,
    )?;
    Ok((transcript, capacity_overflowed))
}

pub(super) fn run_path_get(
    state: &mut OramState,
    spec: &StateObject,
    key: &Value,
    allocator: &mut AllocatorSession,
    leaf_coins: &mut PathOramLeafCoinSource,
    rng: &mut ChaCha20Rng,
) -> Result<(Value, OramTranscript, bool)> {
    let leaf_count = state.parameters.leaf_count();
    let fresh_leaf = leaf_coins.take_leaf(&spec.name, leaf_count, rng)?;
    let access_leaf = access_leaf_for_key(&state.entries, &state.position_map, key, fresh_leaf);
    let slot = slot_for_key(&state.entries, key);
    let slot_present = slot.is_some();
    let prior_leaf = select_position_map_leaf(&state.position_map, &slot);
    let fresh_leaf_option = MaskedUsizeOption::some(fresh_leaf);
    let no_next_leaf = MaskedUsizeOption::none();
    let next_leaf = masked_select_option_usize(slot_present, &fresh_leaf_option, &no_next_leaf);
    let return_value = select_entry_value_for_slot(&state.entries, &slot, &spec.value_type)?;
    let (writes, update_failed) = rewrite_path_for_access(
        state,
        spec,
        access_leaf,
        allocator,
        rng,
        |_entries, position_map, stash, _rng| {
            apply_path_get_update(position_map, stash, &slot, &next_leaf);
            Ok(false)
        },
    )?;
    let mut transcript = path_access_transcript(state, spec, access_leaf)?;
    transcript.physical_writes = writes;
    transcript.path_transition = Some(RuntimePathOramTransitionWitness {
        object_id: spec.id,
        object_name: spec.name.clone(),
        bucket_count: state.parameters.bucket_count,
        kind: masked_select_transition_kind(
            slot_present,
            RuntimePathOramTransitionKind::ReadHit,
            RuntimePathOramTransitionKind::ReadMiss,
        ),
        fresh_leaf: next_leaf.unwrap_or(access_leaf),
        slot_index: slot.to_witness(),
        prior_leaf: prior_leaf.to_witness(),
        next_leaf: next_leaf.to_witness(),
    });
    Ok((return_value, transcript, update_failed))
}

pub(super) fn run_path_put(
    state: &mut OramState,
    spec: &StateObject,
    key: Value,
    value: Value,
    apply: bool,
    allocator: &mut AllocatorSession,
    leaf_coins: &mut PathOramLeafCoinSource,
    rng: &mut ChaCha20Rng,
) -> Result<(OramTranscript, bool)> {
    let leaf_count = state.parameters.leaf_count();
    let slot = slot_for_key(&state.entries, &key);
    let slot_present = slot.is_some();
    let prior_leaf = select_position_map_leaf(&state.position_map, &slot);
    let miss_access_leaf = leaf_coins.take_leaf(&spec.name, leaf_count, rng)?;
    let access_leaf = masked_select_usize(
        prior_leaf.is_some(),
        prior_leaf.unwrap_or(0),
        miss_access_leaf,
    );
    let value_is_zero = value.confidential_is_zero_like();
    let request_insert = apply & !slot_present & !value_is_zero;
    let vacant_slot = allocate_slot(&state.entries);
    let no_insert_slot = MaskedUsizeOption::none();
    let insert_slot = masked_select_option_usize(request_insert, &vacant_slot, &no_insert_slot);
    let insert_slot_present = insert_slot.is_some();
    let update_existing = apply & slot_present & !value_is_zero;
    let delete_existing = apply & slot_present & value_is_zero;
    let insert_new = apply & !slot_present & !value_is_zero & insert_slot_present;
    let next_leaf_value = leaf_coins.take_leaf(&spec.name, leaf_count, rng)?;
    let selected_next_leaf = MaskedUsizeOption::some(next_leaf_value);
    let no_next_leaf = MaskedUsizeOption::none();
    let next_leaf = masked_select_option_usize(
        update_existing | insert_new,
        &selected_next_leaf,
        &no_next_leaf,
    );
    let mut transition_kind = RuntimePathOramTransitionKind::WriteNoop;
    transition_kind = masked_select_transition_kind(
        insert_new,
        RuntimePathOramTransitionKind::WriteInsert,
        transition_kind,
    );
    transition_kind = masked_select_transition_kind(
        update_existing,
        RuntimePathOramTransitionKind::WriteUpdate,
        transition_kind,
    );
    transition_kind = masked_select_transition_kind(
        delete_existing,
        RuntimePathOramTransitionKind::WriteDelete,
        transition_kind,
    );
    let transition_slot = masked_select_option_usize(insert_new, &insert_slot, &slot);
    let mut transition_next_leaf = MaskedUsizeOption::none();
    let retained_prior_leaf =
        masked_select_option_usize(!apply & slot_present, &prior_leaf, &transition_next_leaf);
    assign_masked_usize_option(&mut transition_next_leaf, &retained_prior_leaf);
    let updated_transition_next_leaf = masked_select_option_usize(
        update_existing | insert_new,
        &next_leaf,
        &transition_next_leaf,
    );
    assign_masked_usize_option(&mut transition_next_leaf, &updated_transition_next_leaf);
    let transition_fresh_leaf = transition_next_leaf.unwrap_or(access_leaf);
    let transition = RuntimePathOramTransitionWitness {
        object_id: spec.id,
        object_name: spec.name.clone(),
        bucket_count: state.parameters.bucket_count,
        kind: transition_kind,
        fresh_leaf: transition_fresh_leaf,
        slot_index: transition_slot.to_witness(),
        prior_leaf: prior_leaf.to_witness(),
        next_leaf: transition_next_leaf.to_witness(),
    };
    let (writes, update_failed) = rewrite_path_for_access(
        state,
        spec,
        access_leaf,
        allocator,
        rng,
        |entries, position_map, stash, _rng| {
            apply_path_put_update(
                spec,
                entries,
                position_map,
                stash,
                &key,
                &value,
                apply,
                &slot,
                &insert_slot,
                &next_leaf,
            )
        },
    )?;
    let mut transcript = path_access_transcript(state, spec, access_leaf)?;
    transcript.physical_writes = writes;
    transcript.path_transition = Some(transition);
    Ok((transcript, update_failed))
}

pub(super) fn empty_map_entry(spec: &StateObject) -> Result<MapEntry> {
    Ok(MapEntry::new(
        false,
        Value::zero_for_type(
            spec.key_type
                .as_ref()
                .ok_or_else(|| anyhow!("map {} missing key type", spec.name))?,
        ),
        Value::zero_for_type(&spec.value_type),
    ))
}

pub(super) fn decode_surrogate_entries_from_storage_into(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    directory_pages: &[Box<[u8]>],
    allocator: &mut AllocatorSession,
    empty_entry: &MapEntry,
    entries: &mut [MapEntry],
) -> Result<()> {
    if entries.len() != parameters.capacity {
        bail!(
            "surrogate ORAM entry buffer length {} mismatched public slot count {} for {}",
            entries.len(),
            parameters.capacity,
            spec.name
        );
    }
    for entry in entries.iter_mut() {
        entry.wipe_secrets();
        assign_map_entry(entry, empty_entry);
    }
    let mut next_entry_index = 0usize;
    for (page_index, page) in directory_pages.iter().enumerate() {
        if next_entry_index == parameters.capacity {
            break;
        }
        let remaining = parameters.capacity - next_entry_index;
        with_opened_oram_payload(
            format!("{}@meta{}", spec.name, page_index),
            oram_meta_aad(spec, page_index),
            parameters.directory_page_bytes,
            page,
            cipher,
            allocator,
            |payload| -> Result<()> {
                let entry_tail = entries.get_mut(next_entry_index..).ok_or_else(|| {
                    anyhow!(
                        "surrogate directory decode tail index {} missing despite capacity guard for {}",
                        next_entry_index,
                        spec.name
                    )
                })?;
                let decoded =
                    decode_oram_directory_page_into_slice(payload, spec, remaining, entry_tail)?;
                next_entry_index += decoded;
                Ok(())
            },
        )?;
    }
    Ok(())
}

pub(super) fn empty_oram_block(spec: &StateObject) -> Result<OramBlock> {
    Ok(OramBlock {
        occupied: false,
        slot_index: 0,
        leaf: 0,
        key: Value::zero_for_type(
            spec.key_type
                .as_ref()
                .ok_or_else(|| anyhow!("map {} missing key type", spec.name))?,
        ),
        value: Value::zero_for_type(&spec.value_type),
    })
}

pub(super) fn fixed_stash_with_capacity(spec: &StateObject, capacity: usize) -> Result<FixedStash> {
    let empty_block = empty_oram_block(spec)?;
    Ok(FixedStash {
        empty_block: clone_oram_block(&empty_block),
        blocks: repeat_boxed_oram_blocks(capacity, &empty_block)?,
        len: 0,
        overflowed: false,
    })
}

pub(super) fn clear_fixed_stash(stash: &mut FixedStash) {
    for block in &mut stash.blocks {
        block.wipe_secrets();
        assign_oram_block(block, &stash.empty_block);
    }
    stash.len = 0;
    stash.overflowed = false;
}

pub(super) fn cold_commit_oram_state(
    position_map: &mut [MaskedUsizeOption],
    entries: &mut [MapEntry],
    empty_entry: &MapEntry,
    stash: &mut FixedStash,
) {
    for leaf in position_map.iter_mut() {
        *leaf = MaskedUsizeOption::none();
    }
    for entry in entries.iter_mut() {
        entry.wipe_secrets();
        assign_map_entry(entry, empty_entry);
    }
    clear_fixed_stash(stash);
}

pub(super) fn path_position_map_witness_leaves(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    directory_pages: &[Box<[u8]>],
) -> Result<Box<[RuntimeMaskedUsizeOptionWitness]>> {
    let position_map = path_position_map_from_storage(spec, parameters, cipher, directory_pages)?;
    position_map_to_witness_boxed(&position_map)
}

pub(super) fn position_map_to_witness_boxed(
    position_map: &[MaskedUsizeOption],
) -> Result<Box<[RuntimeMaskedUsizeOptionWitness]>> {
    let mut leaves = FixedBoxBuilder::new(position_map.len());
    for leaf in position_map {
        leaves.push(leaf.to_witness())?;
    }
    leaves.finish()
}

pub(super) fn push_fixed_stash(stash: &mut FixedStash, block: OramBlock) -> Result<()> {
    push_fixed_stash_with_limit(stash, block, stash.blocks.len())
}

pub(super) fn push_fixed_stash_with_limit(
    stash: &mut FixedStash,
    block: OramBlock,
    limit: usize,
) -> Result<()> {
    let should_insert = block.occupied;
    let slot = select_stash_index_with_limit(stash, limit, |candidate| !candidate.occupied);
    let slot_present = slot.is_some();
    stash.overflowed |= should_insert & !slot_present;
    let slot_index = slot.unwrap_or(0);
    for (index, candidate) in stash.blocks.iter_mut().enumerate() {
        let insert_here = should_insert & slot_present & (index == slot_index);
        *candidate = select_oram_block(insert_here, &block, candidate)?;
    }
    stash.len += usize::from(should_insert & slot_present);
    Ok(())
}

pub(super) fn install_path_entry_from_block_if_occupied(
    spec: &StateObject,
    entries: &mut [MapEntry],
    block: &OramBlock,
) -> Result<()> {
    let slot_in_range = block.slot_index < entries.len();
    let invalid_slot = block.occupied & !slot_in_range;
    if invalid_slot {
        bail!(
            "decoded ORAM live block for {} references out-of-range slot {}",
            spec.name,
            block.slot_index
        );
    }
    let slot_index = masked_select_usize(slot_in_range, block.slot_index, 0);
    let candidate = MapEntry::new(true, block.key.clone(), block.value.clone());
    for (index, entry) in entries.iter_mut().enumerate() {
        let write_here = block.occupied & (index == slot_index);
        *entry = select_map_entry(write_here, &candidate, entry)?;
    }
    Ok(())
}

pub(super) fn oram_block_from_entry(entry: &MapEntry) -> OramBlock {
    OramBlock {
        occupied: entry.is_occupied(),
        slot_index: 0,
        leaf: 0,
        key: entry.key().clone(),
        value: entry.value().clone(),
    }
}

pub(super) fn oram_bucket_with_live_blocks(
    spec: &StateObject,
    access_counter: u64,
    bucket_index: usize,
    live_entry_count: usize,
    blocks: &[OramBlock],
) -> Result<OramBucket> {
    let parameters = OramParameters::for_spec(spec)?;
    if blocks.len() > parameters.blocks_per_bucket {
        bail!(
            "ORAM bucket {} for {} carries {} blocks beyond public budget {}",
            bucket_index,
            spec.name,
            blocks.len(),
            parameters.blocks_per_bucket
        );
    }
    let empty_block = empty_oram_block(spec)?;
    let mut fixed_blocks = repeat_boxed_oram_blocks(parameters.blocks_per_bucket, &empty_block)?;
    for (slot, block) in blocks.iter().enumerate() {
        let target = fixed_blocks.get_mut(slot).ok_or_else(|| {
            anyhow!(
                "ORAM bucket {} for {} live block slot {} missing despite public block budget {}",
                bucket_index,
                spec.name,
                slot,
                parameters.blocks_per_bucket
            )
        })?;
        assign_oram_block(target, block);
    }
    Ok(OramBucket {
        access_counter,
        bucket_index,
        live_entry_count,
        blocks: fixed_blocks,
    })
}

pub(super) fn oram_bucket_from_entries(
    spec: &StateObject,
    entries: &[MapEntry],
    access_counter: u64,
    bucket_index: usize,
) -> Result<OramBucket> {
    let parameters = OramParameters::for_spec(spec)?;
    let live_entry_count = entries.iter().fold(0usize, |count, entry| {
        count + usize::from(entry.is_occupied())
    });
    let empty_block = empty_oram_block(spec)?;
    let mut fixed_blocks = repeat_boxed_oram_blocks(parameters.blocks_per_bucket, &empty_block)?;
    let mut consumed = 0usize;
    for slot in fixed_blocks.iter_mut() {
        let target_rank = consumed;
        let mut rank = 0usize;
        let mut found = false;
        let mut selected = clone_oram_block(&empty_block);
        for entry in entries.iter() {
            let occupied = entry.is_occupied();
            let take_here = occupied & !found & (rank == target_rank);
            let entry_block = oram_block_from_entry(entry);
            selected = select_oram_block(take_here, &entry_block, &selected)?;
            found |= take_here;
            rank += usize::from(occupied);
        }
        *slot = selected;
        consumed += usize::from(found);
    }
    Ok(OramBucket {
        access_counter,
        bucket_index,
        live_entry_count,
        blocks: fixed_blocks,
    })
}

pub(super) fn build_path_bucket(
    spec: &StateObject,
    parameters: &OramParameters,
    bucket_index: usize,
    stash: &mut FixedStash,
) -> Result<OramBucket> {
    let empty_block = empty_oram_block(spec)?;
    let mut fixed_blocks = repeat_boxed_oram_blocks(parameters.blocks_per_bucket, &empty_block)?;
    let mut live_entry_count = 0usize;
    for slot in fixed_blocks.iter_mut() {
        let candidate_index = select_stash_index(stash, |block| {
            block.occupied && bucket_on_leaf_path(parameters.leaf_count(), bucket_index, block.leaf)
        });
        let present = candidate_index.is_some();
        *slot = take_selected_stash_block(stash, candidate_index.unwrap_or(0), present)?;
        live_entry_count += usize::from(present);
    }
    Ok(OramBucket {
        access_counter: 0,
        bucket_index,
        live_entry_count,
        blocks: fixed_blocks,
    })
}

pub(super) fn oram_directory_page_count(capacity: usize) -> usize {
    capacity.max(1).div_ceil(ORAM_DIRECTORY_PAGE_ENTRIES)
}

fn checked_end(start: usize, len: usize, context: &str) -> Result<usize> {
    start
        .checked_add(len)
        .ok_or_else(|| anyhow!("ORAM codec range overflow while {context}"))
}

fn read_exact_range<'a>(
    bytes: &'a [u8],
    start: usize,
    len: usize,
    context: &str,
) -> Result<&'a [u8]> {
    let end = checked_end(start, len, context)?;
    bytes.get(start..end).ok_or_else(|| {
        anyhow!(
            "ORAM codec input too short while {context}: range {}..{} exceeds {}",
            start,
            end,
            bytes.len()
        )
    })
}

fn copy_exact_into(out: &mut [u8], input: &[u8], context: &str) -> Result<()> {
    if out.len() != input.len() {
        bail!(
            "ORAM codec exact copy length mismatch while {context}: {} != {}",
            out.len(),
            input.len()
        );
    }
    for (target, byte) in out.iter_mut().zip(input.iter()) {
        *target = *byte;
    }
    Ok(())
}

fn write_exact_range(out: &mut [u8], start: usize, bytes: &[u8], context: &str) -> Result<usize> {
    let end = checked_end(start, bytes.len(), context)?;
    let out_len = out.len();
    let target = out.get_mut(start..end).ok_or_else(|| {
        anyhow!(
            "ORAM codec output too short while {context}: range {}..{} exceeds {}",
            start,
            end,
            out_len
        )
    })?;
    copy_exact_into(target, bytes, context)?;
    Ok(end)
}

fn read_u64_be_at(bytes: &[u8], start: usize, context: &str) -> Result<u64> {
    let mut word = [0u8; 8];
    let word_bytes = read_exact_range(bytes, start, 8, context)?;
    copy_exact_into(&mut word, word_bytes, context)?;
    Ok(u64::from_be_bytes(word))
}

fn write_u64_be_at(out: &mut [u8], start: usize, value: u64, context: &str) -> Result<usize> {
    write_exact_range(out, start, &value.to_be_bytes(), context)
}

pub(super) fn serialize_oram_block_into(
    block: &OramBlock,
    spec: &StateObject,
    out: &mut [u8],
) -> Result<()> {
    let key_type = spec
        .key_type
        .as_ref()
        .ok_or_else(|| anyhow!("map {} missing key type", spec.name))?;
    let key_len = fixed_scalar_width(key_type)?;
    let value_len = fixed_scalar_width(&spec.value_type)?;
    let path_bytes = if spec.oram_scheme == PATH_ORAM_SCHEME {
        ORAM_SLOT_INDEX_BYTES + ORAM_LEAF_LABEL_BYTES
    } else {
        0
    };
    let expected_len = 1 + path_bytes + key_len + value_len;
    if out.len() != expected_len {
        bail!(
            "unexpected ORAM block buffer length for {}: {} != {}",
            spec.name,
            out.len(),
            expected_len
        );
    }
    let mut cursor = write_exact_range(
        out,
        0,
        &[u8::from(block.occupied)],
        "writing ORAM block tag",
    )?;
    if spec.oram_scheme == PATH_ORAM_SCHEME {
        cursor = write_u64_be_at(
            out,
            cursor,
            u64::try_from(block.slot_index)
                .map_err(|_| anyhow!("slot index overflow for {}", spec.name))?,
            "writing ORAM block slot index",
        )?;
        cursor = write_u64_be_at(
            out,
            cursor,
            u64::try_from(block.leaf)
                .map_err(|_| anyhow!("leaf label overflow for {}", spec.name))?,
            "writing ORAM block leaf label",
        )?;
    }
    let mut overflowed = false;
    let mut copy_chunk = |chunk: &[u8]| {
        if overflowed {
            overflowed = true;
            return;
        }
        match write_exact_range(out, cursor, chunk, "writing ORAM block canonical chunk") {
            Ok(end) => cursor = end,
            Err(_) => overflowed = true,
        }
    };
    block.key.visit_canonical_chunks(&mut copy_chunk);
    block.value.visit_canonical_chunks(&mut copy_chunk);
    if overflowed || cursor != out.len() {
        bail!("ORAM block canonical encoding drifted from exact output length");
    }
    Ok(())
}

pub(super) fn deserialize_oram_block(spec: &StateObject, bytes: &[u8]) -> Result<OramBlock> {
    let key_type = spec
        .key_type
        .as_ref()
        .ok_or_else(|| anyhow!("map {} missing key type", spec.name))?;
    let key_len = fixed_scalar_width(key_type)?;
    let value_len = fixed_scalar_width(&spec.value_type)?;
    let path_bytes = if spec.oram_scheme == PATH_ORAM_SCHEME {
        ORAM_SLOT_INDEX_BYTES + ORAM_LEAF_LABEL_BYTES
    } else {
        0
    };
    let expected_len = 1 + path_bytes + key_len + value_len;
    if bytes.len() != expected_len {
        bail!(
            "unexpected ORAM block length for {}: {} != {}",
            spec.name,
            bytes.len(),
            expected_len
        );
    }
    let occupied_tag = *read_exact_range(bytes, 0, 1, "reading ORAM block tag")?
        .first()
        .ok_or_else(|| anyhow!("ORAM block tag missing for {}", spec.name))?;
    let occupied = match occupied_tag {
        0 => false,
        1 => true,
        other => bail!("invalid ORAM block tag {other:#x} for {}", spec.name),
    };
    let (slot_index, leaf, key_start) = if spec.oram_scheme == PATH_ORAM_SCHEME {
        (
            usize::try_from(read_u64_be_at(bytes, 1, "reading ORAM block slot index")?)
                .map_err(|_| anyhow!("slot index overflow for {}", spec.name))?,
            usize::try_from(read_u64_be_at(bytes, 9, "reading ORAM block leaf label")?)
                .map_err(|_| anyhow!("leaf label overflow for {}", spec.name))?,
            17,
        )
    } else {
        (0, 0, 1)
    };
    Ok(OramBlock {
        occupied,
        slot_index,
        leaf,
        key: decode_scalar_value(
            key_type,
            read_exact_range(bytes, key_start, key_len, "reading ORAM block key")?,
        )?,
        value: decode_scalar_value(
            &spec.value_type,
            read_exact_range(
                bytes,
                key_start + key_len,
                value_len,
                "reading ORAM block value",
            )?,
        )?,
    })
}

pub(super) fn encode_path_stash_page_into(
    spec: &StateObject,
    parameters: &OramParameters,
    stash: &[OramBlock],
    empty_block: &OramBlock,
    out: &mut [u8],
) -> Result<()> {
    if out.len() != parameters.directory_page_bytes {
        bail!(
            "unexpected ORAM stash page buffer length for {}: {} != {}",
            spec.name,
            out.len(),
            parameters.directory_page_bytes
        );
    }
    for index in 0..ORAM_DIRECTORY_PAGE_ENTRIES {
        let block = stash.get(index).unwrap_or(empty_block);
        let start = index * parameters.block_size;
        let end = start + parameters.block_size;
        let target = out.get_mut(start..end).ok_or_else(|| {
            anyhow!(
                "ORAM stash page block range {}..{} missing despite exact page size for {}",
                start,
                end,
                spec.name
            )
        })?;
        serialize_oram_block_into(block, spec, target)?;
    }
    Ok(())
}

pub(super) fn encode_path_position_map_page_into(
    spec: &StateObject,
    parameters: &OramParameters,
    position_map: &[MaskedUsizeOption],
    out: &mut [u8],
) -> Result<()> {
    if out.len() != parameters.directory_page_bytes {
        bail!(
            "unexpected ORAM metadata page buffer length for {}: {} != {}",
            spec.name,
            out.len(),
            parameters.directory_page_bytes
        );
    }
    out.fill(0);
    let mut cursor = 0usize;
    for entry in position_map.iter().take(ORAM_DIRECTORY_PAGE_ENTRIES) {
        let encoded = u64::try_from(entry.unwrap_or(usize::MAX))
            .map_err(|_| anyhow!("leaf label overflow for {}", spec.name))?;
        cursor = write_u64_be_at(
            out,
            cursor,
            encoded,
            "writing Path-ORAM position-map page entry",
        )?;
    }
    Ok(())
}

pub(super) fn encode_path_metadata_pages(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    position_map: &[MaskedUsizeOption],
    stash: &[OramBlock],
    allocator: &mut AllocatorSession,
    rng: &mut ChaCha20Rng,
) -> Result<Box<[Box<[u8]>]>> {
    let mut pages = repeat_boxed_empty_byte_boxes(parameters.metadata_pages)?;
    let mut next_page = 0usize;
    for page in 0..parameters.position_map_pages() {
        let mut payload = zeroed_boxed_bytes(parameters.directory_page_bytes)?;
        encode_path_position_map_page_into(
            spec,
            parameters,
            directory_page_entries(position_map, page),
            payload.as_mut(),
        )?;
        let aad = oram_meta_aad(spec, page);
        let page_slot = pages.get_mut(next_page).ok_or_else(|| {
            anyhow!(
                "metadata page index {} missing despite public page-count guard for {}",
                next_page,
                spec.name
            )
        })?;
        *page_slot = seal_boxed_oram_payload(&aad, payload.as_mut(), cipher, rng, Some(allocator))?;
        next_page += 1;
    }
    let empty_block = empty_oram_block(spec)?;
    for page in 0..parameters.stash_pages() {
        let mut payload = zeroed_boxed_bytes(parameters.directory_page_bytes)?;
        encode_path_stash_page_into(
            spec,
            parameters,
            directory_page_entries(stash, page),
            &empty_block,
            payload.as_mut(),
        )?;
        let aad = oram_meta_aad(spec, parameters.position_map_pages() + page);
        let page_slot = pages.get_mut(next_page).ok_or_else(|| {
            anyhow!(
                "metadata page index {} missing despite public page-count guard for {}",
                next_page,
                spec.name
            )
        })?;
        *page_slot = seal_boxed_oram_payload(&aad, payload.as_mut(), cipher, rng, Some(allocator))?;
        next_page += 1;
    }
    if next_page != pages.len() {
        bail!(
            "path metadata page rewrite initialized {} pages, expected {}",
            next_page,
            pages.len()
        );
    }
    Ok(pages)
}

pub(super) fn rewrite_path_metadata_pages_in_place(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    position_map: &[MaskedUsizeOption],
    stash: &[OramBlock],
    allocator: &mut AllocatorSession,
    rng: &mut ChaCha20Rng,
    directory_pages: &mut [Box<[u8]>],
    writes: &mut OramWriteLog,
) -> Result<()> {
    if directory_pages.len() != parameters.metadata_pages {
        bail!(
            "directory page count {} did not match public metadata page count {} for {}",
            directory_pages.len(),
            parameters.metadata_pages,
            spec.name
        );
    }
    let mut payload = zeroed_boxed_bytes(parameters.directory_page_bytes)?;
    for page in 0..parameters.position_map_pages() {
        let directory_page = directory_pages.get_mut(page).ok_or_else(|| {
            anyhow!(
                "path ORAM position-map page index {} missing despite public count guard for {}",
                page,
                spec.name
            )
        })?;
        encode_path_position_map_page_into(
            spec,
            parameters,
            directory_page_entries(position_map, page),
            payload.as_mut(),
        )?;
        reseal_oram_payload_and_record_write(
            writes,
            format!("{}@meta{page}", spec.name),
            oram_meta_aad(spec, page),
            payload.as_mut(),
            directory_page,
            cipher,
            rng,
            allocator,
        )?;
    }
    let empty_block = empty_oram_block(spec)?;
    for page in 0..parameters.stash_pages() {
        encode_path_stash_page_into(
            spec,
            parameters,
            directory_page_entries(stash, page),
            &empty_block,
            payload.as_mut(),
        )?;
        let page_index = parameters.position_map_pages() + page;
        let directory_page = directory_pages.get_mut(page_index).ok_or_else(|| {
            anyhow!(
                "path ORAM stash page index {} missing despite public count guard for {}",
                page_index,
                spec.name
            )
        })?;
        reseal_oram_payload_and_record_write(
            writes,
            format!("{}@meta{page_index}", spec.name),
            oram_meta_aad(spec, page_index),
            payload.as_mut(),
            directory_page,
            cipher,
            rng,
            allocator,
        )?;
    }
    Ok(())
}

#[cfg_attr(not(test), allow(dead_code))]
pub(super) fn decode_path_metadata_pages(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    pages: &[Box<[u8]>],
    allocator: &mut AllocatorSession,
) -> Result<(Box<[MaskedUsizeOption]>, FixedStash)> {
    let mut position_map =
        repeat_boxed_masked_usize_options(parameters.capacity, &MaskedUsizeOption::none())?;
    let mut stash = fixed_stash_with_capacity(spec, working_stash_capacity(parameters)?)?;
    decode_path_metadata_pages_into(
        spec,
        parameters,
        cipher,
        pages,
        allocator,
        &mut position_map,
        &mut stash,
    )?;
    Ok((position_map, stash))
}

pub(super) fn decode_path_metadata_pages_into(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    pages: &[Box<[u8]>],
    allocator: &mut AllocatorSession,
    position_map: &mut [MaskedUsizeOption],
    stash: &mut FixedStash,
) -> Result<()> {
    let required_metadata_pages = parameters
        .position_map_pages()
        .checked_add(parameters.stash_pages())
        .ok_or_else(|| {
            anyhow!(
                "ORAM metadata page count overflowed public bound for {}",
                spec.name
            )
        })?;
    if pages.len() != required_metadata_pages {
        bail!(
            "metadata page count {} mismatched public bound {} for {}",
            pages.len(),
            required_metadata_pages,
            spec.name
        );
    }
    decode_path_position_map_pages_into(spec, parameters, cipher, pages, allocator, position_map)?;
    let required_stash_capacity = working_stash_capacity(parameters)?;
    clear_fixed_stash(stash);
    if stash.capacity() < required_stash_capacity {
        bail!(
            "stash buffer capacity {} fell below required public bound {} for {}",
            stash.capacity(),
            required_stash_capacity,
            spec.name
        );
    }
    for page in 0..parameters.stash_pages() {
        let page_index = parameters.position_map_pages() + page;
        with_opened_oram_payload(
            format!("{}@meta{}", spec.name, page_index),
            oram_meta_aad(spec, page_index),
            parameters.directory_page_bytes,
            pages.get(page_index).ok_or_else(|| {
                anyhow!(
                    "metadata page index {} missing despite public page-count guard for {}",
                    page_index,
                    spec.name
                )
            })?,
            cipher,
            allocator,
            |payload| -> Result<()> {
                for block_bytes in payload.chunks_exact(parameters.block_size) {
                    let block = deserialize_oram_block(spec, block_bytes)?;
                    let occupied = block.occupied;
                    if occupied & (block.slot_index >= parameters.capacity) {
                        bail!(
                            "decoded ORAM stash for {} references out-of-range slot {}",
                            spec.name,
                            block.slot_index
                        );
                    }
                    if occupied & (block.leaf >= parameters.leaf_count()) {
                        bail!(
                            "decoded ORAM stash for {} carries out-of-range leaf {}",
                            spec.name,
                            block.leaf
                        );
                    }
                    push_fixed_stash_with_limit(stash, block, parameters.stash_bound)?;
                }
                Ok(())
            },
        )?;
    }
    if stash.overflowed() {
        bail!(
            "decoded ORAM stash for {} exceeds manifest bound {}",
            spec.name,
            parameters.stash_bound
        );
    }
    Ok(())
}

pub(super) fn load_path_buckets_into_stash(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    buckets: &[Box<[u8]>],
    access_leaf: usize,
    allocator: &mut AllocatorSession,
    stash: &mut FixedStash,
) -> Result<()> {
    if buckets.len() != parameters.bucket_count {
        bail!(
            "path ORAM bucket count {} mismatched public bucket count {} for {}",
            buckets.len(),
            parameters.bucket_count,
            spec.name
        );
    }
    let mut load_result = Ok(());
    for_each_bucket_on_leaf_path_root_to_leaf(
        parameters.leaf_count(),
        access_leaf,
        |bucket_index| {
            if load_result.is_err() {
                return;
            }
            load_result = (|| -> Result<()> {
                let bucket = buckets.get(bucket_index).ok_or_else(|| {
                    anyhow!(
                        "path ORAM bucket index {} missing despite public count guard for {}",
                        bucket_index,
                        spec.name
                    )
                })?;
                with_opened_oram_payload(
                    format!("{}@bucket{}", spec.name, bucket_index),
                    oram_bucket_aad(spec, bucket_index),
                    parameters.bucket_size,
                    bucket,
                    cipher,
                    allocator,
                    |payload| {
                        decode_bucket_payload(spec, bucket_index, payload, |block| {
                            push_fixed_stash(stash, block)
                        })
                    },
                )?;
                Ok(())
            })();
        },
    );
    load_result
}

pub(super) fn rebuild_path_buckets_from_stash(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    buckets: &mut [Box<[u8]>],
    access_leaf: usize,
    allocator: &mut AllocatorSession,
    rng: &mut ChaCha20Rng,
    writes: &mut OramWriteLog,
    stash: &mut FixedStash,
) -> Result<()> {
    if buckets.len() != parameters.bucket_count {
        bail!(
            "path ORAM bucket count {} mismatched public bucket count {} for {}",
            buckets.len(),
            parameters.bucket_count,
            spec.name
        );
    }
    let mut rebuild_result = Ok(());
    for_each_bucket_on_leaf_path_leaf_to_root(
        parameters.leaf_count(),
        access_leaf,
        |bucket_index| {
            if rebuild_result.is_err() {
                return;
            }
            rebuild_result = (|| -> Result<()> {
                let bucket = build_path_bucket(spec, parameters, bucket_index, stash)?;
                let mut payload = oram_bucket_bytes(&bucket, spec)?;
                let sealed_bucket = buckets.get_mut(bucket_index).ok_or_else(|| {
                    anyhow!(
                        "path ORAM bucket index {} missing despite public count guard for {}",
                        bucket_index,
                        spec.name
                    )
                })?;
                reseal_oram_payload_and_record_write(
                    writes,
                    format!("{}@bucket{}", spec.name, bucket_index),
                    oram_bucket_aad(spec, bucket_index),
                    payload.as_mut(),
                    sealed_bucket,
                    cipher,
                    rng,
                    allocator,
                )?;
                Ok(())
            })();
        },
    );
    rebuild_result
}

pub(super) fn rewrite_path_for_access<F>(
    state: &mut OramState,
    spec: &StateObject,
    access_leaf: usize,
    allocator: &mut AllocatorSession,
    rng: &mut ChaCha20Rng,
    update: F,
) -> Result<(OramWriteBatch, bool)>
where
    F: FnOnce(
        &mut [MapEntry],
        &mut [MaskedUsizeOption],
        &mut FixedStash,
        &mut ChaCha20Rng,
    ) -> Result<bool>,
{
    let mut writes = oram_write_log_with_capacity(oram_write_log_capacity(&state.parameters)?)?;
    let mut working_entries = std::mem::take(&mut state.entries);
    let mut working_position_map = std::mem::take(&mut state.position_map);
    let mut working_stash = std::mem::replace(&mut state.stash, FixedStash::placeholder());
    let required_stash_capacity = working_stash_capacity(&state.parameters)?;
    if working_stash.capacity() < required_stash_capacity {
        bail!(
            "working stash capacity {} fell below required public bound {} for {}",
            working_stash.capacity(),
            required_stash_capacity,
            spec.name
        );
    }

    load_path_buckets_into_stash(
        spec,
        &state.parameters,
        &state.cipher,
        &state.storage.buckets,
        access_leaf,
        allocator,
        &mut working_stash,
    )?;
    let mut update_failed = working_stash.overflowed();

    let effect_failed = update(
        &mut working_entries,
        &mut working_position_map,
        &mut working_stash,
        rng,
    )?;
    update_failed |= effect_failed;
    update_failed |=
        working_stash.len() > state.parameters.stash_bound + state.parameters.buckets_per_access;

    rebuild_path_buckets_from_stash(
        spec,
        &state.parameters,
        &state.cipher,
        &mut state.storage.buckets,
        access_leaf,
        allocator,
        rng,
        &mut writes,
        &mut working_stash,
    )?;

    update_failed |= working_stash.len() > state.parameters.stash_bound;

    rewrite_path_metadata_pages_in_place(
        spec,
        &state.parameters,
        &state.cipher,
        &working_position_map,
        working_stash.as_slice(),
        allocator,
        rng,
        &mut state.storage.directory_pages,
        &mut writes,
    )?;

    let next_counter = state.access_counter + 1;
    rewrite_oram_counter_in_place(
        spec,
        next_counter,
        &state.cipher,
        allocator,
        rng,
        &mut state.storage.access_counter_slot,
        &mut writes,
    )?;

    state.entries = working_entries;
    state.position_map = working_position_map;
    state.stash = working_stash;
    state.access_counter = next_counter;
    Ok((finish_oram_write_log(writes)?, update_failed))
}

pub(super) fn reconstruct_path_entries_from_storage_into(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    buckets: &[Box<[u8]>],
    allocator: &mut AllocatorSession,
    empty_entry: &MapEntry,
    position_map: &[MaskedUsizeOption],
    stash: &FixedStash,
    entries: &mut [MapEntry],
) -> Result<()> {
    if entries.len() != parameters.capacity {
        bail!(
            "entry buffer length {} mismatched required public bound {} for {}",
            entries.len(),
            parameters.capacity,
            spec.name
        );
    }
    if buckets.len() != parameters.bucket_count {
        bail!(
            "path ORAM bucket count {} mismatched public bucket count {} for {}",
            buckets.len(),
            parameters.bucket_count,
            spec.name
        );
    }
    for entry in entries.iter_mut() {
        entry.wipe_secrets();
        assign_map_entry(entry, empty_entry);
        entry.set_vacant(empty_entry.value().clone());
        entry.set_value(empty_entry.value().clone());
    }
    let mut live_slots =
        repeat_boxed_masked_usize_options(parameters.capacity, &MaskedUsizeOption::none())?;
    for block in stash.blocks.iter() {
        validate_live_path_block(spec, parameters, position_map, &mut live_slots, block)?;
        install_path_entry_from_block_if_occupied(spec, entries, block)?;
    }
    for index in 0..parameters.bucket_count {
        let bucket = buckets.get(index).ok_or_else(|| {
            anyhow!(
                "path ORAM bucket index {} missing despite public count guard for {}",
                index,
                spec.name
            )
        })?;
        with_opened_oram_payload(
            format!("{}@bucket{}", spec.name, index),
            oram_bucket_aad(spec, index),
            parameters.bucket_size,
            bucket,
            cipher,
            allocator,
            |payload| {
                decode_bucket_payload(spec, index, payload, |block| {
                    let off_path = block.occupied
                        & !bucket_on_leaf_path(parameters.leaf_count(), index, block.leaf);
                    if off_path {
                        bail!(
                            "decoded ORAM bucket {} for {} carries leaf {} off its path",
                            index,
                            spec.name,
                            block.leaf
                        );
                    }
                    validate_live_path_block(
                        spec,
                        parameters,
                        position_map,
                        &mut live_slots,
                        &block,
                    )?;
                    install_path_entry_from_block_if_occupied(spec, entries, &block)?;
                    Ok(())
                })
            },
        )?;
    }
    for (slot_index, leaf) in position_map.iter().enumerate() {
        let live_slot = live_slots.get(slot_index).ok_or_else(|| {
            anyhow!(
                "live-slot index {} missing despite public capacity guard for {}",
                slot_index,
                spec.name
            )
        })?;
        if leaf.is_some() & !live_slot.is_some() {
            bail!(
                "decoded ORAM position map for {} references missing live block at slot {}",
                spec.name,
                slot_index
            );
        }
    }
    Ok(())
}

pub(super) fn refresh_path_state_from_storage(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    directory_pages: &[Box<[u8]>],
    buckets: &[Box<[u8]>],
    allocator: &mut AllocatorSession,
    empty_entry: &MapEntry,
    position_map: &mut [MaskedUsizeOption],
    stash: &mut FixedStash,
    entries: &mut [MapEntry],
) -> Result<()> {
    decode_path_metadata_pages_into(
        spec,
        parameters,
        cipher,
        directory_pages,
        allocator,
        position_map,
        stash,
    )?;
    reconstruct_path_entries_from_storage_into(
        spec,
        parameters,
        cipher,
        buckets,
        allocator,
        empty_entry,
        position_map,
        stash,
        entries,
    )?;
    Ok(())
}

pub(super) fn decode_path_position_map_pages(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    pages: &[Box<[u8]>],
    allocator: &mut AllocatorSession,
) -> Result<Box<[MaskedUsizeOption]>> {
    let mut position_map =
        repeat_boxed_masked_usize_options(parameters.capacity, &MaskedUsizeOption::none())?;
    decode_path_position_map_pages_into(
        spec,
        parameters,
        cipher,
        pages,
        allocator,
        &mut position_map,
    )?;
    Ok(position_map)
}

pub(super) fn path_position_map_from_storage(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    directory_pages: &[Box<[u8]>],
) -> Result<Box<[MaskedUsizeOption]>> {
    let scratch = parameters.directory_page_bytes.max(8);
    let mut allocator = AllocatorSession::new(AllocatorPlan {
        arena_bytes: scratch.saturating_mul(4),
        max_stack_words: 0,
        scratch_bytes: scratch,
        max_kernel_ops: 0,
    })?;
    let position_map =
        decode_path_position_map_pages(spec, parameters, cipher, directory_pages, &mut allocator)?;
    allocator.finish()?;
    Ok(position_map)
}

pub(super) fn decode_path_position_map_pages_into(
    spec: &StateObject,
    parameters: &OramParameters,
    cipher: &StoreCipher,
    pages: &[Box<[u8]>],
    allocator: &mut AllocatorSession,
    position_map: &mut [MaskedUsizeOption],
) -> Result<()> {
    if position_map.len() != parameters.capacity {
        bail!(
            "position-map buffer length {} mismatched public bound {} for {}",
            position_map.len(),
            parameters.capacity,
            spec.name
        );
    }
    let required_position_pages = parameters.position_map_pages();
    if pages.len() < required_position_pages {
        bail!(
            "position-map page count {} below public bound {} for {}",
            pages.len(),
            required_position_pages,
            spec.name
        );
    }
    for leaf in position_map.iter_mut() {
        *leaf = MaskedUsizeOption::none();
    }
    let mut next_slot = 0usize;
    for page in 0..parameters.position_map_pages() {
        with_opened_oram_payload(
            format!("{}@meta{}", spec.name, page),
            oram_meta_aad(spec, page),
            parameters.directory_page_bytes,
            pages.get(page).ok_or_else(|| {
                anyhow!(
                    "position-map page index {} missing despite public page-count guard for {}",
                    page,
                    spec.name
                )
            })?,
            cipher,
            allocator,
            |payload| -> Result<()> {
                for (entry_index, _) in payload
                    .chunks_exact(ORAM_LEAF_LABEL_BYTES)
                    .take(ORAM_DIRECTORY_PAGE_ENTRIES)
                    .enumerate()
                {
                    if next_slot == position_map.len() {
                        break;
                    }
                    let offset =
                        entry_index
                            .checked_mul(ORAM_LEAF_LABEL_BYTES)
                            .ok_or_else(|| {
                                anyhow!("ORAM position-map entry offset overflow for {}", spec.name)
                            })?;
                    let value = read_u64_be_at(
                        payload,
                        offset,
                        "reading Path-ORAM position-map page entry",
                    )?;
                    let present = value != u64::MAX;
                    let masked_value = masked_select_u64(present, value, 0);
                    let leaf = usize::try_from(masked_value)
                        .map_err(|_| anyhow!("leaf label overflow for {}", spec.name))?;
                    if present & (leaf >= parameters.leaf_count()) {
                        bail!(
                            "decoded ORAM position map for {} carries out-of-range leaf {}",
                            spec.name,
                            leaf
                        );
                    }
                    let target = position_map.get_mut(next_slot).ok_or_else(|| {
                        anyhow!(
                            "position map slot {} missing despite public capacity guard for {}",
                            next_slot,
                            spec.name
                        )
                    })?;
                    *target = MaskedUsizeOption::new(present, leaf);
                    next_slot += 1;
                }
                Ok(())
            },
        )?;
    }
    if next_slot != position_map.len() {
        bail!(
            "decoded ORAM position map for {} produced {} entries, expected {}",
            spec.name,
            next_slot,
            position_map.len()
        );
    }
    Ok(())
}

pub(super) fn serialize_oram_bucket_into(
    bucket: &OramBucket,
    spec: &StateObject,
    out: &mut [u8],
) -> Result<()> {
    let parameters = OramParameters::for_spec(spec)?;
    if bucket.blocks.len() != parameters.blocks_per_bucket {
        bail!(
            "unexpected ORAM bucket block count for {}: {} != {}",
            spec.name,
            bucket.blocks.len(),
            parameters.blocks_per_bucket
        );
    }
    if out.len() != parameters.bucket_size {
        bail!(
            "unexpected ORAM bucket buffer length for {}: {} != {}",
            spec.name,
            out.len(),
            parameters.bucket_size
        );
    }
    let mut cursor = write_u64_be_at(
        out,
        0,
        bucket.access_counter,
        "writing ORAM bucket access counter",
    )?;
    cursor = write_u64_be_at(
        out,
        cursor,
        u64::try_from(bucket.bucket_index)
            .map_err(|_| anyhow!("bucket index overflow for {}", spec.name))?,
        "writing ORAM bucket index",
    )?;
    cursor = write_u64_be_at(
        out,
        cursor,
        u64::try_from(bucket.live_entry_count)
            .map_err(|_| anyhow!("live entry count overflow for {}", spec.name))?,
        "writing ORAM bucket live entry count",
    )?;
    for block in &bucket.blocks {
        let end = cursor + parameters.block_size;
        let target = out.get_mut(cursor..end).ok_or_else(|| {
            anyhow!(
                "ORAM bucket block range {}..{} missing despite exact bucket size for {}",
                cursor,
                end,
                spec.name
            )
        })?;
        serialize_oram_block_into(block, spec, target)?;
        cursor = end;
    }
    if cursor != out.len() {
        bail!(
            "serialized ORAM bucket length for {} drifted: {} != {}",
            spec.name,
            cursor,
            out.len()
        );
    }
    Ok(())
}

pub(super) fn oram_bucket_bytes(bucket: &OramBucket, spec: &StateObject) -> Result<Box<[u8]>> {
    let parameters = OramParameters::for_spec(spec)?;
    let mut out = zeroed_boxed_bytes(parameters.bucket_size)?;
    serialize_oram_bucket_into(bucket, spec, &mut out)?;
    Ok(out)
}

pub(super) fn deserialize_oram_bucket(spec: &StateObject, bytes: &[u8]) -> Result<OramBucket> {
    let parameters = OramParameters::for_spec(spec)?;
    if bytes.len() != parameters.bucket_size {
        bail!(
            "unexpected ORAM bucket length for {}: {} != {}",
            spec.name,
            bytes.len(),
            parameters.bucket_size
        );
    }
    let block_size = parameters.block_size;
    let access_counter = read_u64_be_at(bytes, 0, "reading ORAM bucket access counter")?;
    let bucket_index = usize::try_from(read_u64_be_at(bytes, 8, "reading ORAM bucket index")?)
        .map_err(|_| anyhow!("bucket index overflow for {}", spec.name))?;
    let live_entry_count = usize::try_from(read_u64_be_at(
        bytes,
        16,
        "reading ORAM bucket live entry count",
    )?)
    .map_err(|_| anyhow!("live entry count overflow for {}", spec.name))?;
    let empty_block = empty_oram_block(spec)?;
    let mut fixed_blocks = repeat_boxed_oram_blocks(parameters.blocks_per_bucket, &empty_block)?;
    let block_payload_len = parameters
        .bucket_size
        .checked_sub(ORAM_BUCKET_HEADER_BYTES)
        .ok_or_else(|| anyhow!("ORAM bucket header exceeds bucket size for {}", spec.name))?;
    let block_payload = read_exact_range(
        bytes,
        ORAM_BUCKET_HEADER_BYTES,
        block_payload_len,
        "reading ORAM bucket block payload",
    )?;
    for (slot, block) in block_payload.chunks_exact(block_size).enumerate() {
        let target = fixed_blocks.get_mut(slot).ok_or_else(|| {
            anyhow!(
                "ORAM bucket decode slot {} missing despite exact public block count for {}",
                slot,
                spec.name
            )
        })?;
        *target = deserialize_oram_block(spec, block)?;
    }
    Ok(OramBucket {
        access_counter,
        bucket_index,
        live_entry_count,
        blocks: fixed_blocks,
    })
}

pub(super) fn decode_bucket_payload<F>(
    spec: &StateObject,
    expected_bucket_index: usize,
    bytes: &[u8],
    mut on_block: F,
) -> Result<()>
where
    F: FnMut(OramBlock) -> Result<()>,
{
    let parameters = OramParameters::for_spec(spec)?;
    if bytes.len() != parameters.bucket_size {
        bail!(
            "unexpected ORAM bucket length for {}: {} != {}",
            spec.name,
            bytes.len(),
            parameters.bucket_size
        );
    }
    let bucket_index = usize::try_from(read_u64_be_at(
        bytes,
        8,
        "reading ORAM bucket payload index",
    )?)
    .map_err(|_| anyhow!("bucket index overflow for {}", spec.name))?;
    if bucket_index != expected_bucket_index {
        bail!(
            "decoded ORAM bucket header for {} claims index {} but storage location is {}",
            spec.name,
            bucket_index,
            expected_bucket_index
        );
    }
    let live_entry_count = usize::try_from(read_u64_be_at(
        bytes,
        16,
        "reading ORAM bucket payload live entry count",
    )?)
    .map_err(|_| anyhow!("live entry count overflow for {}", spec.name))?;
    if live_entry_count > parameters.blocks_per_bucket {
        bail!(
            "decoded ORAM bucket {} for {} exceeds block budget {}",
            bucket_index,
            spec.name,
            parameters.blocks_per_bucket
        );
    }
    let mut occupied = 0usize;
    let block_payload_len = parameters
        .bucket_size
        .checked_sub(ORAM_BUCKET_HEADER_BYTES)
        .ok_or_else(|| anyhow!("ORAM bucket header exceeds bucket size for {}", spec.name))?;
    let block_payload = read_exact_range(
        bytes,
        ORAM_BUCKET_HEADER_BYTES,
        block_payload_len,
        "reading decoded ORAM bucket payload blocks",
    )?;
    for block in block_payload.chunks_exact(parameters.block_size) {
        let block = deserialize_oram_block(spec, block)?;
        occupied += usize::from(block.occupied);
        on_block(block)?;
    }
    if occupied != live_entry_count {
        bail!(
            "decoded ORAM bucket {} for {} contains {} live blocks but header says {}",
            bucket_index,
            spec.name,
            occupied,
            live_entry_count
        );
    }
    Ok(())
}
